"""Describe the adaptive robustness follow-up without overriding its failed gate."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]/'research/kaos_swing_v1'

def main():
    read=lambda name:json.loads((ROOT/'backfill'/name).read_text());result=read('validation.json');selection=read('selection.json');final=read('confirmation.json');provenance=read('provenance.json');files=provenance['sources'][0]['files'];missing=sum(x.get('missingArchive',False) for x in files);bad=sum(len(x.get('rejectedBars',[])) for x in files)
    lines=['\n## Additional older-regime robustness check\n','After observing a positive but unqualified four-hour breakout family in 2023–2024, a second plan (`backfill_plan.json`, committed as `53ac1d2`) froze **two unchanged configurations** on 2019–2022. This is an adaptive follow-up chosen using the first study, not a newly independent research hypothesis. No stop, indicator, fee or entry/exit rule was tuned.\n',f'2018–2020 hourly archives add past context. **{missing} unavailable archives** are recorded rather than invented, including periods before listings. **{bad} malformed/non-aligned hourly bars** are explicitly excluded and recorded in source metadata; their timestamps are not rounded. Gaps reset indicators and prevent crossing swing trades. The source collector now has offline checks for unavailable archives, rejected alignment and wrong checksums.\n','The follow-up gate requires at least 300 trades and 150 active dates, the unchanged original swing validation conditions, and a lower weekly-bootstrap mean above zero with a 14-way correction (12 original configurations plus 2 follow-ups). At most one setting could advance to the still-unscored 2025 BNB/XRP/ADA confirmation. No further backfill, parameter change or alternate selection follows these results in this round.\n','| 2019–2022 configuration | Trades | Active dates | Net R | PF | Combined-stress net R | Adjusted lower weekly mean R | Eligible |','|---|---:|---:|---:|---:|---:|---:|---|']
    for key,r in result.items():
        b=r['base'];lines.append(f"| {key} | {b['trades']} | {b['days']} | {b['netR']:.2f} | {b['PF']:.3f} | {r['stress']['netR']:.2f} | {b['lower_week_mean']:.3f} | {r['eligible']} |")
    lines.extend([f"\nFollow-up selection: **{selection['selected'] or 'none'}**. Confirmation evaluated: **{selection['confirmation_evaluated']}**. Confirmation gate passed: **{final['qualified']}**.\n",'The four-hour breakout family made historical net gains in both evaluated periods and survived combined cost/entry-delay stress at both stop settings. That is a useful research finding, not a qualified live edge. The older sample is too small for the fixed gate and both settings have negative adjusted confidence bounds. Do not pool the periods post hoc, relax thresholds, or substitute the large portfolio returns to declare success. `backfill/paper_candidate.json` explicitly records the qualification status and disables execution.\n','Raw source arrays remain private workspace artifacts. Reproduce with:\n','```bash','python scripts/collect_swing_history.py --start-year 2018 --end-year 2020 --out /private/older-hourly --cache /private/hourly-cache','python scripts/research_swing_backfill.py --data /private/older-hourly /private/hourly','```\n'])
    p=ROOT/'README.md';p.write_text(p.read_text().split('\n## Additional older-regime robustness check\n')[0]+'\n'.join(lines))
if __name__=='__main__':main()
